// Build one Hacker News search query per keyword
const cfg = $input.first().json;
const keywords = cfg.keywords.split(',').map(k => k.trim()).filter(Boolean);
const sevenDaysAgo = Math.floor(Date.now() / 1000) - (60 * 60 * 24 * 7);

const queries = keywords.map(kw => ({
  keyword: kw,
  url: `https://hn.algolia.com/api/v1/search_by_date?query=${encodeURIComponent(kw)}&numericFilters=created_at_i>${sevenDaysAgo}`
}));

return queries.map(q => ({
  json: {
    ...q,
    slack_webhook_url: cfg.slack_webhook_url,
    google_sheet_id: cfg.google_sheet_id
  }
}));

// Flatten every input item's HN hits into individual output items,
// pulling keyword/config back from Build Search Queries by position
// (the HTTP node's own response replaces those fields on the item).
const httpItems = $input.all();
const queryItems = $('Build HN Search Queries').all();
const results = [];

for (let i = 0; i < httpItems.length; i++) {
  const resp = httpItems[i].json;
  const query = queryItems[i] ? queryItems[i].json : {};
  if (resp.statusCode !== 200 || !resp.body) continue;

  const hits = resp.body.hits || [];
  for (const h of hits) {
    results.push({
      title: h.title || h.story_title || '(comment on a story)',
      url: h.url || `https://news.ycombinator.com/item?id=${h.objectID}`,
      snippet: (h.comment_text || h.story_text || '').replace(/<[^>]*>/g, '').slice(0, 300),
      points: h.points || h.story_points || 0,
      created_at: h.created_at,
      matched_keyword: query.keyword,
      slack_webhook_url: query.slack_webhook_url,
      google_sheet_id: query.google_sheet_id
    });
  }
}

return results.map(r => ({ json: r }));

// Combine candidate posts with already-seen posts (two connections feeding
// this one node), and filter out anything already logged, capped at 20
// per run to stay well within most AI API free-tier rate limits.
const allItems = $input.all().map(i => i.json);
const seenUrls = new Set(allItems.filter(i => i.post_url !== undefined).map(i => i.post_url));
const candidates = allItems.filter(i => i.url !== undefined);
const newCandidates = candidates.filter(c => !seenUrls.has(c.url));
return newCandidates.slice(0, 20).map(c => ({ json: c }));

